package com.arjunren.hospital.repository;
import com.arjunren.hospital.domain.AppointmentStatus;import com.arjunren.hospital.entity.Appointment;import jakarta.persistence.LockModeType;import java.time.Instant;import java.util.Optional;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface AppointmentRepository extends JpaRepository<Appointment,Long>{Page<Appointment>findByPatientUserId(Long id,Pageable p);Page<Appointment>findByDoctorUserId(Long id,Pageable p);@Query("select count(a)>0 from Appointment a where a.doctor.id=:doctor and a.status='SCHEDULED' and a.startsAt<:end and a.endsAt>:start")boolean conflicts(@Param("doctor")Long doctor,@Param("start")Instant start,@Param("end")Instant end);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select a from Appointment a join fetch a.doctor d join fetch d.user join fetch a.patient p join fetch p.user where a.id=:id")Optional<Appointment>findByIdForUpdate(@Param("id")Long id);long countByStatus(AppointmentStatus status);}

